c = json.loads((ROOT / "_build/catalog.json").read_text())
ids = {a["id"] for a in c["assets"]}
for f in sys.argv[1:]:
    key = f.split("_", 1)[1].replace(".png", "")
    for suf in ("_v2", "_v3"):
        if key.endswith(suf):
            key = key[: -len(suf)]
    iid, sh, t, dk, k, d, how, tags = META[key]
    if iid in ids:
        for a in c["assets"]:
            if a["id"] == iid:
                a["src"] = G + f
        print("差し替え:", iid); continue
    desc = d + "のイラストです。"
    c["assets"].append({"id": iid, "src": G + f, "author": "riko", "title": t, "shikaku": sh, "dankai": dk, "kind": k,
                        "uses": ["ホームページ", "説明の紙", "チラシ"], "description": desc, "howto": how,
                        "alt": desc.replace("です。", "。"), "tags": tags})
    ids.add(iid)
(ROOT / "_build/catalog.json").write_text(json.dumps(c, ensure_ascii=False, indent=1))
print(len(c["assets"]), "点")
